// Atomic GitHub create-or-update with retry on 409 SHA conflict.
// Uses helper sub-workflow (webhook) because Code Node has no httpRequestWithAuthentication in n8n 2.35.x.
// Uses LOCALHOST URL because n8n container may not be able to reach its own public URL (NAT loopback).

const params = $('Set Parameters').item.json;
const filename = params.filename;
const content = params.content;
const commitMessage = params.commitMessage;

if (!filename || !commitMessage || content === undefined) {
  throw new Error(`Missing required params: filename=${filename}, commitMessage=${commitMessage}, content=${content === undefined ? 'undefined' : 'set'}`);
}

const helperUrl = 'http://localhost:5678/webhook/github-memory-helper';
const contentBase64 = Buffer.from(content, 'utf8').toString('base64');
const maxRetries = 5;

async function callHelper(action, payload) {
  return await this.helpers.httpRequest({
    method: 'POST',
    url: helperUrl,
    body: { action, ...payload },
    json: true,
    timeout: 20000
  });
}

let lastError = null;
for (let attempt = 1; attempt <= maxRetries; attempt++) {
  // Step 1: GET sha
  let sha = null;
  let exists = false;
  let getRes;
  try {
    getRes = await callHelper.call(this, 'get', { filename });
  } catch (e) {
    throw new Error(`Helper GET call failed (attempt=${attempt}): ${e.message}`);
  }
  const getStatus = getRes.statusCode;
  if (getStatus === 200) {
    sha = getRes.body && getRes.body.sha;
    exists = true;
  } else if (getStatus === 404) {
    exists = false;
  } else {
    throw new Error(`GET failed (status=${getStatus}, attempt=${attempt}): ${JSON.stringify(getRes.body).slice(0, 500)}`);
  }

  // Step 2: PUT (create or update). On 409/422 we retry with refetched SHA.
  let putRes;
  try {
    putRes = await callHelper.call(this, 'put', {
      filename,
      content: contentBase64,
      message: commitMessage,
      sha: exists ? sha : null
    });
  } catch (e) {
    throw new Error(`Helper PUT call failed (attempt=${attempt}): ${e.message}`);
  }
  const putStatus = putRes.statusCode;
  if (putStatus === 200 || putStatus === 201) {
    return [{ json: {
      ok: true,
      attempt,
      action: exists ? 'edited' : 'created',
      filename,
      commit_sha: putRes.body && putRes.body.commit && putRes.body.commit.sha,
      content_sha: putRes.body && putRes.body.content && putRes.body.content.sha,
      commit_url: putRes.body && putRes.body.commit && putRes.body.commit.html_url,
      message: commitMessage
    } }];
  }
  lastError = new Error(`PUT failed (status=${putStatus}, attempt=${attempt}/${maxRetries}): ${JSON.stringify(putRes.body).slice(0, 500)}`);
  if ((putStatus === 409 || putStatus === 422) && attempt < maxRetries) {
    const backoffMs = 200 * Math.pow(2, attempt - 1) + Math.floor(Math.random() * 200);
    await new Promise(r => setTimeout(r, backoffMs));
    continue;
  }
  throw lastError;
}
throw lastError || new Error(`Atomic edit failed after ${maxRetries} retries`);
